interface User {
  id: number
  name: string
  isActive: boolean
}

interface UserStatsProps {
  users: User[]
}

export default function UserStats({ users }: UserStatsProps) {
  // Derived values calculated directly, following the codebase pattern.
  const activeUsers = users.filter((user) => user.isActive).length
  const inactiveUsers = users.length - activeUsers
  const activePercentage = users.length === 0 ? 0 : Math.round((activeUsers / users.length) * 100)

  return (
    <div>
      <h2>User Statistics</h2>
      <p>Active Users: {activeUsers}</p>
      <p>Inactive Users: {inactiveUsers}</p>
      <p>Active Percentage: {activePercentage}%</p>
    </div>
  )
}
